const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Point([-82.5, 26.0]).buffer(50000); // Gulf of Mexico off SW Florida, 50km buffer
  const dateStr1 = '2004-10-30';
  const dateStr2 = '2004-11-21';

  // The MODIS/051/L3_CHL dataset provides 8-day composites.
  // We need to find the composite periods that contain our specific dates.
  // For '2004-10-30', the 8-day composite starting on '2004-10-25' (day of year 299) covers it.
  const period1Start = '2004-10-25';
  const period1End = '2004-11-01'; // 8 days later

  // For '2004-11-21', the 8-day composite starting on '2004-11-17' (day of year 321) covers it.
  const period2Start = '2004-11-17';
  const period2End = '2004-11-24'; // 8 days later

  const collectionId = 'MODIS/051/L3_CHL';
  const bandName = 'chlor_a';
  const scale = 4000; // MODIS/L3_CHL resolution is 4km

  // 2. Data Acquisition & Check for Period 1 (October 30, 2004)
  let col1 = ee.ImageCollection(collectionId)
    .filterDate(period1Start, period1End)
    .filterBounds(region)
    .select(bandName);

  let size1 = col1.size().getInfo();
  if (size1 === 0) {
    console.log("No images found for the period covering October 30, 2004.");
    console.log("C1");
    return;
  }
  let img1 = col1.first();
  console.log(`Period 1 Image (Oct 30): ${img1.date().format('YYYY-MM-dd').getInfo()}`);

  // 2. Data Acquisition & Check for Period 2 (November 21, 2004)
  let col2 = ee.ImageCollection(collectionId)
    .filterDate(period2Start, period2End)
    .filterBounds(region)
    .select(bandName);

  let size2 = col2.size().getInfo();
  if (size2 === 0) {
    console.log("No images found for the period covering November 21, 2004.");
    console.log("C1");
    return;
  }
  let img2 = col2.first();
  console.log(`Period 2 Image (Nov 21): ${img2.date().format('YYYY-MM-dd').getInfo()}`);

  // 3. Processing - Calculate valid pixels and mean chlorophyll
  let stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
  }).getInfo();

  let meanChlor1 = stats1[bandName];
  let count1 = stats1[bandName + '_count'];

  if (count1 === 0) {
    console.log(`No valid pixels for the period covering October 30, 2004 after masking within the region. Pixel count: ${count1}`);
    console.log("C2");
    return;
  }
  console.log(`Oct 30 Period - Mean Chlorophyll: ${meanChlor1 !== null ? meanChlor1.toFixed(3) : 'N/A'}, Valid Pixels: ${count1}`);

  let stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
  }).getInfo();

  let meanChlor2 = stats2[bandName];
  let count2 = stats2[bandName + '_count'];

  if (count2 === 0) {
    console.log(`No valid pixels for the period covering November 21, 2004 after masking within the region. Pixel count: ${count2}`);
    console.log("C2");
    return;
  }
  console.log(`Nov 21 Period - Mean Chlorophyll: ${meanChlor2 !== null ? meanChlor2.toFixed(3) : 'N/A'}, Valid Pixels: ${count2}`);

  // 4. Calculation and 5. Validation & Final Answer
  if (meanChlor1 === null || isNaN(meanChlor1) || meanChlor2 === null || isNaN(meanChlor2)) {
    console.log("C3"); // Calculation failed
    return;
  }

  if (meanChlor2 > meanChlor1) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
